files = {'agent.py': 'from __future__ import annotations\n\nimport asyncio\nimport json\nimport logging\nimport sys\n\nimport uvicorn\n\nfrom logger import DecisionLogger\nfrom poller import polling_loop\nfrom proxy import build_proxy\nfrom scorer import NodeState\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format="%(asctime)s %(levelname)-8s %(name)s  %(message)s",\n)\nlog = logging.getLogger("arp-agent")\n\n\ndef _load_cfg(path: str) -> dict:\n    with open(path) as f:\n        return json.load(f)\n\n\nasync def _run(cfg_path: str) -> None:\n    cfg = _load_cfg(cfg_path)\n\n    nodes = [\n        NodeState(\n            node_id=n["id"],\n            wicklee_url=n["wicklee_url"],\n            inference_url=n["inference_url"],\n        )\n        for n in cfg["nodes"]\n    ]\n\n    decision_logger = DecisionLogger(cfg.get("log_file", "decisions.jsonl"))\n    app = build_proxy(nodes, cfg, decision_logger)\n\n    log.info(\n        "ARP agent starting — port=%d nodes=%d log=%s",\n        cfg["listen_port"],\n        len(nodes),\n        cfg.get("log_file", "decisions.jsonl"),\n    )\n    for n in nodes:\n        log.info(\n            "  node=%s  wicklee=%s  inference=%s",\n            n.node_id,\n            n.wicklee_url,\n            n.inference_url,\n        )\n\n    poll_task = asyncio.create_task(polling_loop(nodes, cfg))\n\n    server = uvicorn.Server(\n        uvicorn.Config(app, host="0.0.0.0", port=cfg["listen_port"], log_level="warning")\n    )\n    try:\n        await server.serve()\n    finally:\n        poll_task.cancel()\n        await asyncio.gather(poll_task, return_exceptions=True)\n\n\nif __name__ == "__main__":\n    cfg_path = sys.argv[1] if len(sys.argv) > 1 else "config.json"\n    asyncio.run(_run(cfg_path))\n', 'scorer.py': 'from __future__ import annotations\n\nimport threading\nfrom dataclasses import dataclass\nfrom typing import Optional\n\n\ndef score_node(health: dict, cfg: dict) -> float:\n    thermal = health["thermal_headroom_pct"] / 100\n    vram = health["vram_headroom_pct"] / 100\n    tok_w = max(0, 1 + health["wes_delta_pct"] / 100)\n\n    w = cfg["scoring"]\n    score = (\n        thermal * w["thermal_headroom_weight"]\n        + vram * w["vram_headroom_weight"]\n        + tok_w * w["tok_w_delta_weight"]\n    )\n\n    if health["wes_delta_pct"] < w["throttle_threshold_pct"]:\n        return 0.0\n    if health["status"] != "healthy":\n        return 0.0\n    if health["vram_headroom_pct"] < 10:\n        return 0.0\n\n    return round(score, 4)\n\n\ndef exclusion_reason(health: dict, cfg: dict) -> Optional[str]:\n    w = cfg["scoring"]\n    if health["status"] != "healthy":\n        return "unhealthy"\n    if health["wes_delta_pct"] < w["throttle_threshold_pct"]:\n        return "throttling"\n    if health["vram_headroom_pct"] < 10:\n        return "vram_low"\n    return None\n\n\n@dataclass\nclass NodeState:\n    node_id: str\n    wicklee_url: str\n    inference_url: str\n    health: Optional[dict] = None\n    score: float = 0.0\n    last_error: Optional[str] = None\n\n    def __post_init__(self) -> None:\n        self._lock = threading.Lock()\n\n    def update(self, health: dict, cfg: dict) -> None:\n        with self._lock:\n            self.health = health\n            self.score = score_node(health, cfg)\n            self.last_error = None\n\n    def set_error(self, error: str) -> None:\n        with self._lock:\n            self.last_error = error\n            self.score = 0.0\n\n    def get_score(self) -> float:\n        with self._lock:\n            return self.score\n\n    def get_health(self) -> Optional[dict]:\n        with self._lock:\n            return dict(self.health) if self.health else None\n', 'poller.py': 'from __future__ import annotations\n\nimport asyncio\nimport logging\nfrom typing import List\n\nimport httpx\n\nfrom scorer import NodeState\n\nlog = logging.getLogger(__name__)\n\n\nasync def _poll_node(node: NodeState, cfg: dict, client: httpx.AsyncClient) -> None:\n    url = f"{node.wicklee_url}/health"\n    try:\n        resp = await client.get(url, timeout=2.0)\n        resp.raise_for_status()\n        health = resp.json()\n        node.update(health, cfg)\n        log.debug("polled node=%s score=%.4f", node.node_id, node.get_score())\n    except Exception as exc:\n        node.set_error(str(exc))\n        log.warning("poll failed node=%s error=%s", node.node_id, exc)\n\n\nasync def polling_loop(nodes: List[NodeState], cfg: dict) -> None:\n    interval = cfg["scoring"]["poll_interval_ms"] / 1000\n    async with httpx.AsyncClient() as client:\n        while True:\n            await asyncio.gather(\n                *[_poll_node(n, cfg, client) for n in nodes],\n                return_exceptions=True,\n            )\n            await asyncio.sleep(interval)\n', 'proxy.py': 'from __future__ import annotations\n\nimport json\nimport time\nimport uuid\nfrom typing import Dict, List, Optional, Tuple\n\nimport httpx\nfrom fastapi import FastAPI, Request, Response\nfrom fastapi.responses import StreamingResponse\n\nfrom logger import DecisionLogger\nfrom scorer import NodeState, exclusion_reason\n\n\ndef _select_node(\n    nodes: List[NodeState],\n    cfg: dict,\n    rr_state: dict,\n) -> Tuple[Optional[NodeState], Dict[str, float], Dict[str, str], str, bool]:\n    scores: Dict[str, float] = {}\n    exclusions: Dict[str, str] = {}\n\n    for node in nodes:\n        health = node.get_health()\n        if health is None:\n            exclusions[node.node_id] = "no_health_data"\n            scores[node.node_id] = 0.0\n            continue\n        s = node.get_score()\n        scores[node.node_id] = s\n        if s == 0.0:\n            exclusions[node.node_id] = exclusion_reason(health, cfg) or "score_zero"\n\n    eligible = [(n, scores[n.node_id]) for n in nodes if scores.get(n.node_id, 0.0) > 0.0]\n\n    if eligible:\n        best = max(eligible, key=lambda x: x[1])\n        return best[0], scores, exclusions, "highest_score", False\n\n    if cfg.get("fallback") == "round_robin":\n        candidates = [n for n in nodes if n.get_health() is not None]\n        if candidates:\n            idx = rr_state["counter"] % len(candidates)\n            rr_state["counter"] += 1\n            return candidates[idx], scores, exclusions, "fallback_round_robin", True\n\n    return None, scores, exclusions, "no_eligible_node", False\n\n\ndef build_proxy(nodes: List[NodeState], cfg: dict, decision_logger: DecisionLogger) -> FastAPI:\n    app = FastAPI(title="ARP Agent")\n    rr_state = {"counter": 0}\n\n    @app.api_route(\n        "/{path:path}",\n        methods=["GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS", "HEAD"],\n    )\n    async def forward(request: Request, path: str) -> Response:\n        request_id = f"req-{uuid.uuid4().hex[:8]}"\n        t_start = time.monotonic()\n\n        node, node_scores, node_exclusions, reason, fallback_used = _select_node(\n            nodes, cfg, rr_state\n        )\n\n        if node is None:\n            decision_logger.record(\n                request_id=request_id,\n                selected_node=None,\n                score=0.0,\n                reason=reason,\n                fallback_used=fallback_used,\n                node_scores=node_scores,\n                node_exclusions=node_exclusions,\n            )\n            return Response(\n                content=json.dumps({"error": "no eligible node available"}),\n                status_code=503,\n                media_type="application/json",\n            )\n\n        score = node_scores.get(node.node_id, 0.0)\n        decision_logger.record(\n            request_id=request_id,\n            selected_node=node.node_id,\n            score=score,\n            reason=reason,\n            fallback_used=fallback_used,\n            node_scores=node_scores,\n            node_exclusions=node_exclusions,\n        )\n\n        body = await request.body()\n        headers = {k: v for k, v in request.headers.items() if k.lower() != "host"}\n        target_url = f"{node.inference_url}/{path}"\n        params = dict(request.query_params)\n\n        is_stream = False\n        try:\n            if body:\n                is_stream = bool(json.loads(body).get("stream", False))\n        except (json.JSONDecodeError, TypeError):\n            pass\n\n        if is_stream:\n            timing: Dict[str, Optional[float]] = {"ttft_ms": None}\n\n            async def _stream():\n                async with httpx.AsyncClient() as client:\n                    async with client.stream(\n                        request.method,\n                        target_url,\n                        content=body,\n                        headers=headers,\n                        params=params,\n                        timeout=120.0,\n                    ) as upstream:\n                        async for chunk in upstream.aiter_bytes():\n                            if timing["ttft_ms"] is None and chunk:\n                                timing["ttft_ms"] = (time.monotonic() - t_start) * 1000\n                            yield chunk\n                decision_logger.update_timing(\n                    request_id,\n                    timing["ttft_ms"],\n                    (time.monotonic() - t_start) * 1000,\n                )\n\n            return StreamingResponse(_stream(), media_type="text/event-stream")\n\n        async with httpx.AsyncClient() as client:\n            upstream = await client.request(\n                method=request.method,\n                url=target_url,\n                content=body,\n                headers=headers,\n                params=params,\n                timeout=120.0,\n            )\n\n        elapsed_ms = (time.monotonic() - t_start) * 1000\n        decision_logger.update_timing(request_id, elapsed_ms, elapsed_ms)\n\n        return Response(\n            content=upstream.content,\n            status_code=upstream.status_code,\n            headers=dict(upstream.headers),\n            media_type=upstream.headers.get("content-type"),\n        )\n\n    return app\n', 'logger.py': 'from __future__ import annotations\n\nimport json\nimport threading\nfrom datetime import datetime, timezone\nfrom typing import Dict, Optional\n\n\ndef _utcnow() -> str:\n    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")\n\n\nclass DecisionLogger:\n    def __init__(self, log_file: str) -> None:\n        self._path = log_file\n        self._file_lock = threading.Lock()\n        self._pending_lock = threading.Lock()\n        self._pending: Dict[str, dict] = {}\n\n    def _write(self, entry: dict) -> None:\n        with self._file_lock:\n            with open(self._path, "a") as f:\n                f.write(json.dumps(entry) + "\\n")\n\n    def record(\n        self,\n        *,\n        request_id: str,\n        selected_node: Optional[str],\n        score: float,\n        reason: str,\n        fallback_used: bool,\n        node_scores: Dict[str, float],\n        node_exclusions: Dict[str, str],\n    ) -> None:\n        entry = {\n            "ts": _utcnow(),\n            "request_id": request_id,\n            "selected_node": selected_node,\n            "score": score,\n            "reason": reason,\n            "fallback_used": fallback_used,\n            "node_scores": node_scores,\n            "node_exclusions": node_exclusions,\n            "ttft_ms": None,\n            "total_ms": None,\n        }\n        with self._pending_lock:\n            self._pending[request_id] = entry\n        self._write(entry)\n\n    def update_timing(\n        self,\n        request_id: str,\n        ttft_ms: Optional[float],\n        total_ms: Optional[float],\n    ) -> None:\n        with self._pending_lock:\n            entry = self._pending.pop(request_id, None)\n        if entry is None:\n            return\n        updated = dict(entry)\n        updated["ttft_ms"] = round(ttft_ms, 2) if ttft_ms is not None else None\n        updated["total_ms"] = round(total_ms, 2) if total_ms is not None else None\n        self._write(updated)\n', 'config.json': '{\n  "listen_port": 8090,\n  "nodes": [\n    {\n      "id": "node-1",\n      "wicklee_url": "http://localhost:8080",\n      "inference_url": "http://localhost:8000"\n    }\n  ],\n  "scoring": {\n    "thermal_headroom_weight": 0.4,\n    "vram_headroom_weight": 0.3,\n    "tok_w_delta_weight": 0.3,\n    "throttle_threshold_pct": -15,\n    "poll_interval_ms": 100\n  },\n  "fallback": "round_robin",\n  "log_file": "decisions.jsonl"\n}\n', 'requirements.txt': 'fastapi>=0.111.0\nhttpx>=0.27.0\nuvicorn[standard]>=0.29.0\n', 'LICENSE': 'MIT License\n\nCopyright (c) 2026 Jeff Geiser\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the "Software"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n', 'README.md': '# arp-agent\n\nA reference implementation of the [ARP (Agentic Resource Protocol)](https://github.com/jeffgeiser/arp-spec) routing agent.\n\n`arp-agent` is a lightweight Python proxy that:\n\n- Polls each inference node\'s Wicklee `/health` endpoint every 100 ms\n- Scores each node using the ARP scoring function (thermal headroom, VRAM headroom, tok/W delta)\n- Routes incoming OpenAI-compatible requests to the highest-scoring eligible node\n- Logs every routing decision as a JSONL entry for downstream analysis\n\n## Quick Start\n\n```bash\npip install -r requirements.txt\npython agent.py config.json\n```\n\nSend any OpenAI-compatible request to `http://localhost:8090`:\n\n```bash\ncurl http://localhost:8090/v1/chat/completions \\\n  -H "Content-Type: application/json" \\\n  -d \'{"model": "qwen2.5-7b-q4_k_m", "messages": [{"role": "user", "content": "hello"}]}\'\n```\n\n## Configuration\n\n```json\n{\n  "listen_port": 8090,\n  "nodes": [\n    {\n      "id": "node-1",\n      "wicklee_url": "http://localhost:8080",\n      "inference_url": "http://localhost:8000"\n    }\n  ],\n  "scoring": {\n    "thermal_headroom_weight": 0.4,\n    "vram_headroom_weight": 0.3,\n    "tok_w_delta_weight": 0.3,\n    "throttle_threshold_pct": -15,\n    "poll_interval_ms": 100\n  },\n  "fallback": "round_robin",\n  "log_file": "decisions.jsonl"\n}\n```\n\n| Field | Description |\n|-------|-------------|\n| `listen_port` | Port the agent listens on |\n| `nodes[].wicklee_url` | URL of the Wicklee health daemon on that node |\n| `nodes[].inference_url` | URL of the inference server (e.g. vLLM) on that node |\n| `scoring.thermal_headroom_weight` | Weight for thermal headroom signal |\n| `scoring.vram_headroom_weight` | Weight for VRAM headroom signal |\n| `scoring.tok_w_delta_weight` | Weight for tok/W efficiency delta signal |\n| `scoring.throttle_threshold_pct` | Nodes below this `wes_delta_pct` are hard-excluded |\n| `scoring.poll_interval_ms` | Health poll interval in ms (default: 100) |\n| `fallback` | `"round_robin"` — used when no node scores above zero |\n| `log_file` | Path to the JSONL decision log |\n\n## Scoring\n\nEach node is scored as:\n\n```\nscore = (thermal_headroom_pct / 100) * thermal_headroom_weight\n      + (vram_headroom_pct / 100)    * vram_headroom_weight\n      + max(0, 1 + wes_delta_pct/100) * tok_w_delta_weight\n```\n\nNodes are hard-excluded (score = 0) when:\n- `status != "healthy"`\n- `wes_delta_pct < throttle_threshold_pct`\n- `vram_headroom_pct < 10`\n\nWhen all nodes score zero, the agent falls back to round-robin over nodes that have any health data.\n\n## Decision Log\n\nEvery request appends one JSONL entry to `decisions.jsonl` at routing time, then a second entry with the same `request_id` after the response completes with timing filled in:\n\n```json\n{"ts":"2026-06-15T09:01:23Z","request_id":"req-abc123","selected_node":"node-1","score":0.847,"reason":"highest_score","fallback_used":false,"node_scores":{"node-1":0.847,"node-2":0.0},"node_exclusions":{"node-2":"throttling"},"ttft_ms":null,"total_ms":null}\n{"ts":"2026-06-15T09:01:26Z","request_id":"req-abc123","selected_node":"node-1","score":0.847,"reason":"highest_score","fallback_used":false,"node_scores":{"node-1":0.847,"node-2":0.0},"node_exclusions":{"node-2":"throttling"},"ttft_ms":312.4,"total_ms":2841.7}\n```\n\n`reason` values:\n- `highest_score` — normal path, best-scoring node selected\n- `fallback_round_robin` — all nodes scored zero, fell back to round-robin\n- `no_eligible_node` — no nodes had health data and fallback is disabled\n\n## File Structure\n\n```\nagent.py        — startup: wires poller + proxy + logger, runs uvicorn\nscorer.py       — ARP scoring function and NodeState\npoller.py       — async background health polling loop\nproxy.py        — OpenAI-compatible FastAPI proxy with score-based routing\nlogger.py       — thread-safe JSONL decision logger with timing updates\nconfig.json     — example single-node configuration\nrequirements.txt\nexamples/\n  two_node_setup.md\n```\n\n## Requirements\n\n- Python 3.10+\n- `httpx`, `fastapi`, `uvicorn`\n\n## ARP Spec\n\nThis agent implements the routing layer described in the [ARP spec](https://github.com/jeffgeiser/arp-spec). The Reconcile flywheel (weight adaptation from outcomes) is v0.2 — this codebase writes the decision log that will train it.\n\n## License\n\nMIT\n', 'examples/two_node_setup.md': '# Two-Node Setup Example\n\nThis example shows how to run `arp-agent` against two local inference nodes,\neach monitored by a Wicklee health daemon.\n\n## Prerequisites\n\n- Two vLLM instances running (e.g. on ports 8000 and 8001)\n- Two Wicklee daemons running against each GPU (e.g. on ports 8080 and 8081)\n- `arp-agent` installed: `pip install -r requirements.txt`\n\n## Config\n\nCreate `config_two_nodes.json`:\n\n```json\n{\n  "listen_port": 8090,\n  "nodes": [\n    {\n      "id": "node-1",\n      "wicklee_url": "http://localhost:8080",\n      "inference_url": "http://localhost:8000"\n    },\n    {\n      "id": "node-2",\n      "wicklee_url": "http://localhost:8081",\n      "inference_url": "http://localhost:8001"\n    }\n  ],\n  "scoring": {\n    "thermal_headroom_weight": 0.4,\n    "vram_headroom_weight": 0.3,\n    "tok_w_delta_weight": 0.3,\n    "throttle_threshold_pct": -15,\n    "poll_interval_ms": 100\n  },\n  "fallback": "round_robin",\n  "log_file": "decisions.jsonl"\n}\n```\n\n## Start the Agent\n\n```bash\npython agent.py config_two_nodes.json\n```\n\nYou should see:\n\n```\n2026-06-15 09:00:00 INFO     arp-agent  ARP agent starting — port=8090 nodes=2 log=decisions.jsonl\n2026-06-15 09:00:00 INFO     arp-agent    node=node-1  wicklee=http://localhost:8080  inference=http://localhost:8000\n2026-06-15 09:00:00 INFO     arp-agent    node=node-2  wicklee=http://localhost:8081  inference=http://localhost:8001\n```\n\n## Send a Test Request\n\n```bash\ncurl http://localhost:8090/v1/chat/completions \\\n  -H "Content-Type: application/json" \\\n  -d \'{\n    "model": "qwen2.5-7b-q4_k_m",\n    "messages": [{"role": "user", "content": "What is 2 + 2?"}],\n    "max_tokens": 50\n  }\'\n```\n\nThe agent routes to the higher-scoring node. Check `decisions.jsonl`:\n\n```\n{"ts":"2026-06-15T09:01:23Z","request_id":"req-abc123","selected_node":"node-2","score":0.812,"reason":"highest_score","fallback_used":false,"node_scores":{"node-1":0.7234,"node-2":0.812},"node_exclusions":{},"ttft_ms":null,"total_ms":null}\n{"ts":"2026-06-15T09:01:26Z","request_id":"req-abc123","selected_node":"node-2","score":0.812,"reason":"highest_score","fallback_used":false,"node_scores":{"node-1":0.7234,"node-2":0.812},"node_exclusions":{},"ttft_ms":287.4,"total_ms":2914.2}\n```\n\n## Mock Wicklee Endpoint (for testing without hardware)\n\nIf you don\'t have real Wicklee daemons, mock them with this small FastAPI server:\n\n```python\n# mock_wicklee.py\nimport sys\nimport uvicorn\nfrom fastapi import FastAPI\n\napp = FastAPI()\n\n@app.get("/health")\ndef health(node_id: str = "node-1", thermal: float = 18.4, vram: float = 63.75, wes_delta: float = -12.4):\n    return {\n        "node_id": node_id,\n        "ts": "2026-06-15T09:00:00Z",\n        "model_loaded": "qwen2.5-7b-q4_k_m",\n        "tok_s": 24.3,\n        "power_w": 38.2,\n        "tok_w": 0.636,\n        "wes_score": 8.4,\n        "wes_delta_pct": wes_delta,\n        "cold_baseline_tok_w": 0.721,\n        "junction_temp_c": 71.2,\n        "thermal_headroom_pct": thermal,\n        "vram_used_gb": 5.8,\n        "vram_total_gb": 16.0,\n        "vram_headroom_pct": vram,\n        "status": "healthy"\n    }\n\nif __name__ == "__main__":\n    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8080\n    uvicorn.run(app, port=port)\n```\n\nRun two mock nodes with different scores:\n\n```bash\n# node-1: moderate thermal (18%), good VRAM (64%)  → score ~0.53\npython mock_wicklee.py 8080 &\n\n# node-2: better thermal (45%), same VRAM (64%)    → score ~0.65\n# tweak the /health defaults in mock_wicklee.py or add a second app variant\npython mock_wicklee.py 8081 &\n\npython agent.py config_two_nodes.json\n```\n\nRequests will consistently route to node-2 while it holds a higher score.\nSimulate throttling by setting `wes_delta_pct` below `-15` on node-2 and\nwatch the agent fall back to node-1.\n'}
os.makedirs("examples", exist_ok=True)
for path, content in files.items():
    with open(path, "w") as f:
        f.write(content)
    print("  wrote", path)
print("done")
